Method.Implementation:
Set tInputFilename=$tr(pFileStream.Filename,"/","\"), tInputFilename=$P(tInputFilename,"\",$L(tInputFilename,"\")) $$$sysTRACE("Got File "_tInputFilename)
Set tIOStream=##class(%IO.FileStream).%New() $$$ASSERT($IsObject(tIOStream)) Do tIOStream.Open(pFileStream.Filename,,..#OpenTimeout,,.tSC) Quit:$$$ISERR(tSC) tSC
// vsr batch hl7 buil set parent = ##class(EnsLib.HL7.Message).%New() set parent.DocType = ..MessageSchemaCategory_":BHS" set tSC = ..SendRequestAsync(..TargetConfigNames,parent,0)
Do ..%Parser.Reset() While 'tIOStream.AtEnd { ; Loop over docs in the file Set tSC1=..%Parser.ParseFramedIOStream(tIOStream,,1) Set:$$$ISERR(tSC1) tSC=$$$ADDSC(tSC,tSC1) Quit:$$$StatusEquals(tSC1,$$$EnsErrGeneral) // !!! quit on fatal errors only } Do ..%Parser.Reset() ; release the file
// vsr batch hl7 build set parent = ##class(EnsLib.HL7.Message).%New() set parent.DocType = ..MessageSchemaCategory_":BTS" set tSC = ..SendRequestAsync(..TargetConfigNames,parent,0)
Quit tSC
